 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    await scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    // var usrCBData ="전체^(null),일반^1,벤처^2,기술정상^3,대형^4,스팩^5,스팩합병^6,분할재상장^7,외국기업^8";
    // cmb_INVSTG_CD.CBData =  usrCBData;

    //  기간 from~ to  셋팅
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_BILL_STRT_DD.setValue($c.ut.cGetMinusDate2(vCurDate, 365)); // 일년 날짜
    edt_BILL_END_DD.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜
    $c.stf.comboCbDataSetPeriod(cmb_PeriodTp1);
    edt_COMITE_STRT_DD.setValue($c.ut.cGetMinusDate2(vCurDate, 365)); // 일년 날짜
    edt_COMITE_END_DD.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜
    $c.stf.comboCbDataSetPeriod(cmb_PeriodTp2);
};

/**
 * @method
 * @name setBzProcsNo
 * @description set Bz Procs No 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setBzProcsNo = function(obj) {
    scwin.vBzProcsNo = dts_List.getCellData(Number(obj), "BZ_PROCS_NO");
};

/**
 * @method
 * @name getBzProcsNo
 * @description get Bz Procs No 처리
 * @returns {void}
 * @hidden N
 */
scwin.getBzProcsNo = function() {
    return scwin.vBzProcsNo;
};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    let V_INVSTG_CD = " ";
    const V_ISSUE = " ";
    const V_RSN = " ";
    let V_RSLT = " ";
    let previousChecked = false;
    V_INVSTG_CD = "AND ( ";
    if (chk_INVSTG_CD2.checked) {
        if (previousChecked) {
            V_INVSTG_CD += "OR GEN_INVSTG_YN  = '1'  ";
        } else {
            V_INVSTG_CD += "GEN_INVSTG_YN  = '1'  ";
        }
        previousChecked = true;
    }
    if (chk_INVSTG_CD3.checked) {
        if (previousChecked) {
            V_INVSTG_CD += "OR VENT_INVSTG_YN  = '1'  ";
        } else {
            V_INVSTG_CD += "VENT_INVSTG_YN  = '1'  ";
        }
        previousChecked = true;
    }
    if (chk_INVSTG_CD4.checked) {
        if (previousChecked) {
            V_INVSTG_CD += "OR SKIL_GRWTH_INVSTG_YN  = '1'  ";
        } else {
            V_INVSTG_CD += "SKIL_GRWTH_INVSTG_YN  = '1'  ";
        }
        previousChecked = true;
    }
    if (chk_INVSTG_CD5.checked) {
        if (previousChecked) {
            V_INVSTG_CD += "OR BIG_CORP_INVSTG_YN  = '1'  ";
        } else {
            V_INVSTG_CD += "BIG_CORP_INVSTG_YN  = '1'  ";
        }
        previousChecked = true;
    }
    if (chk_INVSTG_CD6.checked) {
        // 우회상장심사
        if (previousChecked) {
            V_INVSTG_CD += " OR BACKLIST_INVSTG_YN  = '1'  ";
        } else {
            V_INVSTG_CD += "BACKLIST_INVSTG_YN  = '1'  ";
        }
        previousChecked = true;
    }
    if (chk_INVSTG_CD7.checked) {
        if (previousChecked) {
            V_INVSTG_CD += "OR SPEC_MERGE_INVSTG_YN  = '1'  ";
        } else {
            V_INVSTG_CD += " SPEC_MERGE_INVSTG_YN  = '1'  ";
        }
        previousChecked = true;
    }
    if (chk_INVSTG_CD8.checked) {
        if (previousChecked) {
            V_INVSTG_CD += "OR SPLIT_RELIST_INVSTG_YN  = '1'  ";
        } else {
            V_INVSTG_CD += " SPLIT_RELIST_INVSTG_YN  = '1'  ";
        }
        previousChecked = true;
    }
    if (chk_INVSTG_CD9.checked) {
        if (previousChecked) {
            V_INVSTG_CD += "OR FORN_COM_INVSTG_YN  = '1'  ";
        } else {
            V_INVSTG_CD += " FORN_COM_INVSTG_YN  = '1'  ";
        }
        previousChecked = true;
    }
    if (previousChecked) {
        V_INVSTG_CD += ") ";
    } else {
        V_INVSTG_CD = "";
    }
    previousChecked = false;
    V_RSLT = " AND COMITE_INVSTG_RSLT_CD IN ( ";
    if (chk_COMITE_RSLT1.checked) {
        V_RSLT += " '1' ";
        previousChecked = true;
    }
    if (chk_COMITE_RSLT2.checked) {
        if (previousChecked) {
            V_RSLT += ", '2' ";
        } else {
            V_RSLT += " '2' ";
        }
        previousChecked = true;
    }
    if (chk_COMITE_RSLT3.checked) {
        if (previousChecked) {
            V_RSLT += ", '3' ";
        } else {
            V_RSLT += " '3' ";
        }
        previousChecked = true;
    }
    if (chk_COMITE_RSLT4.checked) {
        if (previousChecked) {
            V_RSLT += ", '4' ";
        } else {
            V_RSLT += " '4' ";
        }
        previousChecked = true;
    }
    if (previousChecked) {
        V_RSLT += " ) ";
    } else {
        V_RSLT = "";
    }
    const fileContents = $c.ut.trim(txb_FileContent.getValue());
    if (fileContents.length > 0) {
        mgrd_Grid.show("");
        grd_Grid.hide();
    } else {
        mgrd_Grid.hide();
        grd_Grid.show("");
    }
    const stdIndCd = txb_STD_IND_CD.getValue() === '' ? "A" : txb_STD_IND_CD.getValue();
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/ComiteDelib.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name excelDown
 * @description 정보를 excel로 다운 받는다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDown = async function() {
    if (dts_List.getRowCount() > 0) {
        // 엑셀 로그
        $c.stf.doLogSave("ULDSTF60002.xml", SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "리스트", type: "3"});
    } else {
        await $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};

/**
 * @method
 * @name getParStdInd
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParStdInd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_STD_IND_CD.getValue(); // 코드값을 포함할 컨트롤
    arrPar[1] = txb_STD_IND_NM.getValue(); // 명칭값을 포함할 컨트롤

    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParStdInd
 * @description set Par Std Ind 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParStdInd = function(arrPar) {
    txb_STD_IND_CD.setValue(arrPar[0].STD_IND_CD);
    txb_STD_IND_NM.setValue(arrPar[0].IND_NM);
};

/**
 * @method
 * @name getParIssue
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIssue = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = dts_Issue;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParIssue
 * @description set Par Issue 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIssue = function(arrPar) {
    tbx_isue_contn.setValue(arrPar[0].ISUE);
    tbx_napprov_rsn.setValue(arrPar[0].NAPPROV);
    tbx_isue_contn_search.setValue(arrPar[0].ISUE_SEARCH_TEXT);
    tbx_napprov_rsn_search.setValue(arrPar[0].NAPPROV_SEARCH_TEXT);
    $c.stf.copyDataSet(arrPar[0].DTS_ISSUE, dts_Issue);
    // dts_Issue.ResetStatus();

};

/**
 * @method
 * @name setIssue
 * @description set Issue 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setIssue = async function() {
    const sbmOptions = {
        id : "sbm_dts_Issue",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Issue=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};
frame.SetEvent("onwinstat", OnWinStat);
scwin.gOldWidthSize = frame.width;

/**
 * @method
 * @name OnSized
 * @description On Sized 처리
 * @param {String} winID winID
 * @returns {void}
 * @hidden N
 */
scwin.OnSized = function(winID) {
    if (scwin.iTimer > 0) window.clearInterval(scwin.iTimer);
    scwin.iTimer = 0;
    scwin.gNewWidthSize = frame.width;
    // gNewHeightSize = frame.height;
    scwin.GauceObjResize(frame.width, frame.height);
};

/**
 * @method
 * @name OnSizedMax
 * @description On Sized Max 처리
 * @param {String} winID winID
 * @returns {void}
 * @hidden N
 */
scwin.OnSizedMax = function(winID) {
    if (scwin.iTimer > 0) window.clearInterval(scwin.iTimer);
    scwin.iTimer = 0;
    scwin.maxval = 0;
    // alert(frame.width);
    scwin.GauceObjResize($c.frame.path("/").width - 10, frame.height);
};

/**
 * @method
 * @name OnWinStat
 * @description On Win Stat 처리
 * @param {String} winID winID
 * @param {*} statmsg statmsg
 * @returns {void}
 * @hidden N
 */
scwin.OnWinStat = function(winID, statmsg) {
    if (statmsg === "activate" && winID.substring(0, 6) === "Child_") {
        // frameMain의 함수 호출
        $c.frame.path("/").WinActive(winID, statmsg);
    }
    if (statmsg === "maximize") {
        scwin.maxval = 1;
    } else if (statmsg === "size") {
        if (scwin.maxval === 0) {
            const strFnc = "OnSized('" + winID + "')";
            if (scwin.iTimer > 0) {
                window.clearInterval(scwin.iTimer);
                scwin.iTimer = 0;
            }
            scwin.iTimer = window.setInterval(strFnc, 300);
        } else if (scwin.maxval === 1) {
            scwin.OnSizedMax(winID);
            scwin.gOldWidthSize = $c.frame.path("/").width - 10;
        }
    }
};

/**
 * @method
 * @name GauceObjResize
 * @description Gauce Obj Resize 처리
 * @param {*} a a
 * @param {*} b b
 * @returns {void}
 * @hidden N
 */
scwin.GauceObjResize = function(a, b) {
    let gw;
    let ew;

    // GRID 처리
    grd_Grid.ReDraw = "false";
    gw = grd_Grid.getStyle("width");
    ew = a - parseInt(gw) - 35;
    grd_Grid.setGridWidth(parseInt(gw) + ew);
    grd_Grid.ReDraw = "true";
    scwin.gOldWidthSize = frame.width;
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    if ($c.stf.compareFromToDate2(edt_BILL_STRT_DD, edt_BILL_END_DD) && $c.stf.compareFromToDate2(edt_COMITE_STRT_DD, edt_COMITE_END_DD)) {
        await scwin.listSync();
    }
};

