/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    scwin.vBzProcsNo = dts_List.getCellData(row, "BZ_PROCS_NO");
    if ("ATTACH_FILE_NM" === colid && dts_List.getCellData(row, "ATTACH_FILE_NM") !== "") {
        // 사전협의보고서
        location.href = "/filedownload.do?SCREN_ID=" + "ULDSTF60002.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&bz_procs_no=" + dts_List.getCellData(row, "BZ_PROCS_NO") + "&attach_seq=1&gubun=37";
    }
    if ("FILE_NM1" === colid && dts_List.getCellData(row, "FILE_NM1") !== "") {
        // 안건파일
        location.href = "/filedownload.do?SCREN_ID=" + "ULDSTF60002.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&bz_procs_no=" + dts_List.getCellData(row, "BZ_PROCS_NO") + "&comite_dd=" + dts_List.getCellData(row, "COMITE_DD") + "&attach_seq=2&gubun=38";
    }
    if (("ISSUE" === colid && dts_List.getCellData(row, "ISSUE") !== "") || ("RSN" === colid && dts_List.getCellData(row, "RSN") !== "")) {
        // 주요 이슈사항,  미승인ㆍ철회사유
        const options = {
            id: "ULDSTF60001",
            title: "주요이슈사항",
            type: "browserPopup",
            width: "820px",
            height: "900px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/lstmgt/ULDSTF60001.gfm", options);
    }
};

/**
 * @method
 * @name txb_FileContent_onkeydown
 * @description txb_FileContent 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_FileContent_onkeydown = async function() {
    if (window.event.keyCode === 13) {
        await scwin.listSync();
    }
};

/**
 * @method
 * @name mgrd_Grid_OnLButtonDblClk
 * @description mgrd Grid On LButton Dbl Clk 처리
 * @param {*} type type
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @param {*} x x
 * @param {*} y y
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.mgrd_Grid_OnLButtonDblClk = async function(type, row, colid, x, y) {
    scwin.vBzProcsNo = dts_List.getCellData(row, "BZ_PROCS_NO");
    if ("ATTACH_FILE_NM" === colid && dts_List.getCellData(row, "ATTACH_FILE_NM") !== "") {
        // 사전협의보고서
        location.href = "/filedownload.do?SCREN_ID=" + "ULDSTF60002.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&bz_procs_no=" + dts_List.getCellData(row, "BZ_PROCS_NO") + "&attach_seq=1&gubun=37";
    }
    if ("FILE_NM1" === colid && dts_List.getCellData(row, "FILE_NM1") !== "") {
        // 안건파일
        location.href = "/filedownload.do?SCREN_ID=" + "ULDSTF60002.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&bz_procs_no=" + dts_List.getCellData(row, "BZ_PROCS_NO") + "&comite_dd=" + dts_List.getCellData(row, "COMITE_DD") + "&attach_seq=2&gubun=38";
    }
    if (("ISSUE" === colid && dts_List.getCellData(row, "ISSUE") !== "") || ("RSN" === colid && dts_List.getCellData(row, "RSN") !== "")) {
        // 주요 이슈사항,  미승인ㆍ철회사유
        const options = {
            id: "ULDSTF60001",
            title: "주요이슈사항",
            type: "browserPopup",
            width: "820px",
            height: "900px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/lstmgt/ULDSTF60001.gfm", options);
    }
};

